    use std::net::SocketAddrV4;

    use overdrive_worker::mtls_intercept::{InterceptError, Result};
    use overdrive_worker::mtls_intercept_port::{InterceptGuard, MtlsIntercept};
    use parking_lot::Mutex;

    #[derive(Debug, Clone)]
    pub enum SimInterceptFault {
        TransparentListener {
            errno: i32,
        },
        TproxyInstall {
            reason: String,
        },
    }

    pub struct SimMtlsIntercept {
        bind_fault: Mutex<Option<SimInterceptFault>>,
        outbound_fault: Mutex<Option<SimInterceptFault>>,
        inbound_fault: Mutex<Option<SimInterceptFault>>,
    }

    struct InertGuard;

    impl InterceptGuard for InertGuard {}

    impl SimMtlsIntercept {
        #[must_use]
        pub const fn new() -> Self {
            Self {
                bind_fault: Mutex::new(None),
                outbound_fault: Mutex::new(None),
                inbound_fault: Mutex::new(None),
            }
        }

        pub fn script_bind_fault(&self, fault: SimInterceptFault) {
            *self.bind_fault.lock() = Some(fault);
        }

        pub fn script_outbound_fault(&self, fault: SimInterceptFault) {
            *self.outbound_fault.lock() = Some(fault);
        }

        pub fn script_inbound_fault(&self, fault: SimInterceptFault) {
            *self.inbound_fault.lock() = Some(fault);
        }

        pub fn clear_faults(&self) {
            *self.bind_fault.lock() = None;
            *self.outbound_fault.lock() = None;
            *self.inbound_fault.lock() = None;
        }
    }

    impl Default for SimMtlsIntercept {
        fn default() -> Self {
            Self::new()
        }
    }

THE MtlsIntercept IMPL materialises an armed SimInterceptFault into a FRESH InterceptError per call — `TransparentListener { addr, source: std::io::Error::from_raw_os_error(errno) }` or `TproxyInstall { reason }` — short-circuiting BEFORE any syscall. Otherwise it binds a plain `std::net::TcpListener::bind(addr)` (mapping a bind failure to InterceptError::TransparentListener) or returns `Ok(Box::new(InertGuard) as Box<dyn InterceptGuard>)`.

STANDING, NOT CONSUME-ON-USE (DFS-4). The armed fault is CLONED per call and left in place; it fires on EVERY subsequent call until re-armed or cleared. This deliberately DIVERGES from SimMtlsResolve's consume-on-use `.take()` shape, and the divergence is the point: a poisoned store handle is transient, whereas a missing CAP_NET_ADMIN or an absent nft binary fails EVERY call. Standing faults also remove call-order dependence — start_alloc calls bind_transparent TWICE (leg-F then leg-C), and consume-on-use would make 'which leg failed' an artifact of ordering rather than the test's explicit choice. This is exactly why SimInterceptFault is Clone: InterceptError is NOT Clone (it carries std::io::Error), so the descriptor must be re-materialisable. Do NOT `.take()` the slot.

